import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Kernel 日报 2026-11-23","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/23.md","filePath":"notes/kernel-digest/2026/11/23.md"}'),t={name:"notes/kernel-digest/2026/11/23.md"};function l(i,e,s,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="kernel-日报-2026-11-23" tabindex="-1">Kernel 日报 2026-11-23 <a class="header-anchor" href="#kernel-日报-2026-11-23" aria-label="Permalink to &quot;Kernel 日报 2026-11-23&quot;">​</a></h1><blockquote><p>生成时间：2026-11-23T01:41:56Z｜共 32 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-23 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_6832e4b9f03f-·-rfc-patch-v1-00-11-unwind-minimal-dwarf-cfi-stack-unwinding-for-x86-arm64-and-riscv" tabindex="-1"><code>6832e4b9f03f</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-1-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 00/11] unwind: Minimal DWARF CFI stack unwinding for x86, arm64, and riscv</a> <a class="header-anchor" href="#_6832e4b9f03f-·-rfc-patch-v1-00-11-unwind-minimal-dwarf-cfi-stack-unwinding-for-x86-arm64-and-riscv" aria-label="Permalink to &quot;`6832e4b9f03f` · [[RFC PATCH v1 00/11] unwind: Minimal DWARF CFI stack unwinding for x86, arm64, and riscv](https://lore.kernel.org/all/20261122235757.3456048-1-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux｜Rust in Linux</em></p><p>该 RFC 系列引入 Minimal DWARF CFI 栈回溯（stack unwinding）机制，同时覆盖用户态延迟调用链（unwind_user / PERF_RECORD_CALLCHAIN_DEFERRED）和内核态栈跟踪（stacktrace.h / HAVE_RELIABLE_STACKTRACE），支持 x86-64、ARM64 和 RISC-V 三种架构，并附带一个独立的 C 语言构建时 .eh_frame 精简工具（scripts/min_eh_frame.c）。该方案使无论是否编译 frame pointer 的二进制都能可靠回溯，且避免引入重复的 .sframe 段。</p><blockquote><p><strong>学习价值</strong>：对理解 perf 调用链采样、DWARF CFI 原理以及跨架构可靠栈回溯的实现非常有价值，是连接 tracing 与二进制格式的优秀学习材料。</p></blockquote><h3 id="f157e86d2e9f-·-tcp-question-about-rst-at-sack-right-most-edge" tabindex="-1"><code>f157e86d2e9f</code> · <a href="https://lore.kernel.org/all/CALkdYjV9G2fPfXK7UYTe4FuXNUBYD+DbM6caVtBT3CAULHHqUQ@mail.gmail.com/" target="_blank" rel="noreferrer">tcp: question about RST at SACK right-most edge</a> <a class="header-anchor" href="#f157e86d2e9f-·-tcp-question-about-rst-at-sack-right-most-edge" aria-label="Permalink to &quot;`f157e86d2e9f` · [tcp: question about RST at SACK right-most edge](https://lore.kernel.org/all/CALkdYjV9G2fPfXK7UYTe4FuXNUBYD+DbM6caVtBT3CAULHHqUQ@mail.gmail.com/)&quot;">​</a></h3><p><em>Eugene Siegel (<a href="mailto:elzeigel@gmail.com" target="_blank" rel="noreferrer">elzeigel@gmail.com</a>)｜netdev｜网络</em></p><p>讨论 e00431bc93bb 引入的行为：TCP RST 在序列号匹配最右侧 SACK 块右边界时即被接受。发帖者认为这降低了伪造 RST 的门槛——攻击者无需猜测 RCV.NXT，只需让一个乱序 segment 入队，再发送位于该 segment 末尾序列号的 RST 即可断开连接。这是对 TCP RST 验证安全性的质疑讨论。</p><blockquote><p><strong>学习价值</strong>：深入探讨 TCP RST/SACK 交互的安全边界，适合学习 TCP 状态机验证逻辑与 off-path 攻击面分析。</p></blockquote><h3 id="a45fd5bb7d24-·-patch-net-rxrpc-bound-the-oob-challenge-queue-per-connection" tabindex="-1"><code>a45fd5bb7d24</code> · <a href="https://lore.kernel.org/all/20261123011320.4032340-1-linma@zju.edu.cn/" target="_blank" rel="noreferrer">[PATCH net] rxrpc: Bound the OOB challenge queue per connection</a> <a class="header-anchor" href="#a45fd5bb7d24-·-patch-net-rxrpc-bound-the-oob-challenge-queue-per-connection" aria-label="Permalink to &quot;`a45fd5bb7d24` · [[PATCH net] rxrpc: Bound the OOB challenge queue per connection](https://lore.kernel.org/all/20261123011320.4032340-1-linma@zju.edu.cn/)&quot;">​</a></h3><p><em>Lin Ma (<a href="mailto:linma@zju.edu.cn" target="_blank" rel="noreferrer">linma@zju.edu.cn</a>)｜netdev｜网络</em></p><p>rxrpc_notify_socket_oob() 将 CHALLENGE 包加入 socket 的 recvmsg_oobq 时没有数量限制，恶意对端可在已有连接上持续发送 CHALLENGE 使队列无界增长，且每个 skb 都持有 connection 引用。由于连接在 CHALLENGE 得到应答前无法推进，保留深层积压毫无意义。补丁为每个连接的 OOB skb 计数并在达到小阈值后丢弃新 CHALLENGE。</p><blockquote><p><strong>学习价值</strong>：典型的网络子系统资源耗尽防护案例，展示如何识别并修复无界队列 DoS 风险。</p></blockquote><h3 id="_1175b8c4e492-·-patch-btrfs-zoned-fix-deadlock-between-freeze-and-reclaim-zones" tabindex="-1"><code>1175b8c4e492</code> · <a href="https://lore.kernel.org/all/20261123012459.436826-1-mc@raidlab.org/" target="_blank" rel="noreferrer">[PATCH] btrfs: zoned: fix deadlock between freeze and RECLAIM_ZONES</a> <a class="header-anchor" href="#_1175b8c4e492-·-patch-btrfs-zoned-fix-deadlock-between-freeze-and-reclaim-zones" aria-label="Permalink to &quot;`1175b8c4e492` · [[PATCH] btrfs: zoned: fix deadlock between freeze and RECLAIM_ZONES](https://lore.kernel.org/all/20261123012459.436826-1-mc@raidlab.org/)&quot;">​</a></h3><p><em>Miroslav Cimerman (<a href="mailto:mc@raidlab.org" target="_blank" rel="noreferrer">mc@raidlab.org</a>)｜lkml｜文件系统与存储</em></p><p>该补丁修复了 btrfs zoned 模式下 freeze 与 RECLAIM_ZONES 之间的死锁：RECLAIM_ZONES 路径中 btrfs_reclaim_block_groups() 通过 sb_start_write() 获取 super write lock，而已持有该锁并等待 data space ticket 的 writer 会与 freeze、reclaim 三方互相等待形成死锁。修复方案是改用 sb_start_write_trylock() 尝试获取锁。</p><blockquote><p><strong>学习价值</strong>：这是一个经典的锁顺序与冻结语义交互的死锁案例，对学习 sb_start_write/freeze_super 机制和 btrfs 空间回收路径非常有价值。</p></blockquote><h3 id="_36585244d182-·-patch-v3-mm-ksm-prevent-zero-page-remapping-during-ksmd-triggered-thp-splits" tabindex="-1"><code>36585244d182</code> · <a href="https://lore.kernel.org/all/20261122-b4-ksm_fixv2-v3-1-f78ea7779746@linux.dev/" target="_blank" rel="noreferrer">[PATCH v3] mm/ksm: prevent zero-page remapping during ksmd-triggered THP splits</a> <a class="header-anchor" href="#_36585244d182-·-patch-v3-mm-ksm-prevent-zero-page-remapping-during-ksmd-triggered-thp-splits" aria-label="Permalink to &quot;`36585244d182` · [[PATCH v3] mm/ksm: prevent zero-page remapping during ksmd-triggered THP splits](https://lore.kernel.org/all/20261122-b4-ksm_fixv2-v3-1-f78ea7779746@linux.dev/)&quot;">​</a></h3><p><em>Nico Pache (Red Hat) (nico.pache@linux.dev)｜linux-mm｜内存管理</em></p><p>commit b1f202060afe 使匿名 THP 分裂时将零页子页重映射到共享 zeropage，但该逻辑对 KSM 触发的 THP 分裂也无条件生效。在 KSM 与 THP=always 同时启用时造成回归：use_zero_pages=1 场景下 KSM 仅想合并单页却导致整个 2MB THP 被释放。补丁在 ksmd 触发的分裂中阻止 zeropage 重映射。</p><blockquote><p><strong>学习价值</strong>：展示了 KSM、THP split 与 shared zeropage 三个机制交互产生的微妙回归，是学习 mm 子系统特性耦合的好案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（2 条）</li><li><strong>网络</strong>（6 条）</li><li><strong>文件系统与存储</strong>（1 条）</li><li><strong>Rust in Linux</strong>（15 条）</li><li><strong>其他动态</strong>（8 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_5a0c587ad01b-·-rfc-patch-mm-hotfixes-unstable-mm-damon-core-cleanup-damos-walk-completed-in-damos-walk-cancel" tabindex="-1"><code>5a0c587ad01b</code> · <a href="https://lore.kernel.org/all/20261122224054.79767-1-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH mm-hotfixes-unstable] mm/damon/core: cleanup damos-&gt;walk_completed in damos_walk_cancel()</a> <a class="header-anchor" href="#_5a0c587ad01b-·-rfc-patch-mm-hotfixes-unstable-mm-damon-core-cleanup-damos-walk-completed-in-damos-walk-cancel" aria-label="Permalink to &quot;`5a0c587ad01b` · [[RFC PATCH mm-hotfixes-unstable] mm/damon/core: cleanup damos-&gt;walk_completed in damos_walk_cancel()](https://lore.kernel.org/all/20261122224054.79767-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>DAMOS walk 在存在多个 scheme 且前一次 walk 被取消时可能只部分执行。每个 damos 结构体有 walk_completed 字段标记该 scheme 的 walk 是否完成，walk 会跳过已完成的 scheme，全部完成后统一重置。本补丁清理 damos_walk_cancel() 中对 walk_completed 的处理，保证多 scheme 场景下一次快照的 walk 语义正确。</p><blockquote><p><strong>学习价值</strong>：有助于理解 DAMON 中 DAMOS walk 的多 scheme 协调机制与取消路径的状态管理。</p></blockquote><h3 id="_36585244d182-·-patch-v3-mm-ksm-prevent-zero-page-remapping-during-ksmd-triggered-thp-splits-1" tabindex="-1"><code>36585244d182</code> · <a href="https://lore.kernel.org/all/20261122-b4-ksm_fixv2-v3-1-f78ea7779746@linux.dev/" target="_blank" rel="noreferrer">[PATCH v3] mm/ksm: prevent zero-page remapping during ksmd-triggered THP splits</a> <a class="header-anchor" href="#_36585244d182-·-patch-v3-mm-ksm-prevent-zero-page-remapping-during-ksmd-triggered-thp-splits-1" aria-label="Permalink to &quot;`36585244d182` · [[PATCH v3] mm/ksm: prevent zero-page remapping during ksmd-triggered THP splits](https://lore.kernel.org/all/20261122-b4-ksm_fixv2-v3-1-f78ea7779746@linux.dev/)&quot;">​</a></h3><p><em>Nico Pache (Red Hat) (nico.pache@linux.dev)｜linux-mm</em></p><p>commit b1f202060afe 使匿名 THP 分裂时将零页子页重映射到共享 zeropage，但该逻辑对 KSM 触发的 THP 分裂也无条件生效。在 KSM 与 THP=always 同时启用时造成回归：use_zero_pages=1 场景下 KSM 仅想合并单页却导致整个 2MB THP 被释放。补丁在 ksmd 触发的分裂中阻止 zeropage 重映射。</p><blockquote><p><strong>学习价值</strong>：展示了 KSM、THP split 与 shared zeropage 三个机制交互产生的微妙回归，是学习 mm 子系统特性耦合的好案例。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="b1507314401b-·-patch-net-next-sctp-copy-endpoint-settings-to-accepted-and-peeled-off-sockets" tabindex="-1"><code>b1507314401b</code> · <a href="https://lore.kernel.org/all/48580ca6a02b588e9c24444801109506da11a9d2.1795396989.git.lucien.xin@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next] sctp: copy endpoint settings to accepted and peeled-off sockets</a> <a class="header-anchor" href="#b1507314401b-·-patch-net-next-sctp-copy-endpoint-settings-to-accepted-and-peeled-off-sockets" aria-label="Permalink to &quot;`b1507314401b` · [[PATCH net-next] sctp: copy endpoint settings to accepted and peeled-off sockets](https://lore.kernel.org/all/48580ca6a02b588e9c24444801109506da11a9d2.1795396989.git.lucien.xin@gmail.com/)&quot;">​</a></h3><p><em>Xin Long (<a href="mailto:lucien.xin@gmail.com" target="_blank" rel="noreferrer">lucien.xin@gmail.com</a>)｜netdev</em></p><p>SCTP 中 accept() 或 SCTP_SOCKOPT_PEELOFF 创建新 socket 时，sctp_endpoint_new() 从网络命名空间 sysctl 和编译期 AUTH 默认值初始化，而非继承监听 socket 的 endpoint 配置。当发生 RFC 9260 5.2.2 规定的 association restart 时，restart INIT ACK 会基于错误的配置协商能力（如 PR-SCTP、ECN、RECONF、ASCONF 等 feature flags）。补丁将监听 socket 的 endpoint 设置复制到新 socket。</p><blockquote><p><strong>学习价值</strong>：可学习 SCTP endpoint 生命周期、socket 继承语义及 association restart 协议行为。</p></blockquote><h3 id="a45fd5bb7d24-·-patch-net-rxrpc-bound-the-oob-challenge-queue-per-connection-1" tabindex="-1"><code>a45fd5bb7d24</code> · <a href="https://lore.kernel.org/all/20261123011320.4032340-1-linma@zju.edu.cn/" target="_blank" rel="noreferrer">[PATCH net] rxrpc: Bound the OOB challenge queue per connection</a> <a class="header-anchor" href="#a45fd5bb7d24-·-patch-net-rxrpc-bound-the-oob-challenge-queue-per-connection-1" aria-label="Permalink to &quot;`a45fd5bb7d24` · [[PATCH net] rxrpc: Bound the OOB challenge queue per connection](https://lore.kernel.org/all/20261123011320.4032340-1-linma@zju.edu.cn/)&quot;">​</a></h3><p><em>Lin Ma (<a href="mailto:linma@zju.edu.cn" target="_blank" rel="noreferrer">linma@zju.edu.cn</a>)｜netdev</em></p><p>rxrpc_notify_socket_oob() 将 CHALLENGE 包加入 socket 的 recvmsg_oobq 时没有数量限制，恶意对端可在已有连接上持续发送 CHALLENGE 使队列无界增长，且每个 skb 都持有 connection 引用。由于连接在 CHALLENGE 得到应答前无法推进，保留深层积压毫无意义。补丁为每个连接的 OOB skb 计数并在达到小阈值后丢弃新 CHALLENGE。</p><blockquote><p><strong>学习价值</strong>：典型的网络子系统资源耗尽防护案例，展示如何识别并修复无界队列 DoS 风险。</p></blockquote><h3 id="_916c2152cfdf-·-patch-net-rxrpc-fix-overread-of-short-key-descriptions" tabindex="-1"><code>916c2152cfdf</code> · <a href="https://lore.kernel.org/all/20261123011302.4032262-1-linma@zju.edu.cn/" target="_blank" rel="noreferrer">[PATCH net] rxrpc: Fix overread of short key descriptions</a> <a class="header-anchor" href="#_916c2152cfdf-·-patch-net-rxrpc-fix-overread-of-short-key-descriptions" aria-label="Permalink to &quot;`916c2152cfdf` · [[PATCH net] rxrpc: Fix overread of short key descriptions](https://lore.kernel.org/all/20261123011302.4032262-1-linma@zju.edu.cn/)&quot;">​</a></h3><p><em>Lin Ma (<a href="mailto:linma@zju.edu.cn" target="_blank" rel="noreferrer">linma@zju.edu.cn</a>)｜netdev</em></p><p>rxrpc_read() 用 memcmp() 长度为 4 检查 key description 是否以 &quot;afs@&quot; 开头，但 description 可以短至一个字符，导致最多越界读取 kmemdup 分配缓冲区之外的两个字节。由于 NUL 终止符在前四字节内，比较结果不受影响，且越界通常限于 slab 对象内，但仍是 out-of-bounds read。</p><blockquote><p><strong>学习价值</strong>：展示了短字符串 memcmp 越界读这类隐蔽 bug 的成因与修复方式，对学习内核内存安全很有价值。</p></blockquote><h3 id="f157e86d2e9f-·-tcp-question-about-rst-at-sack-right-most-edge-1" tabindex="-1"><code>f157e86d2e9f</code> · <a href="https://lore.kernel.org/all/CALkdYjV9G2fPfXK7UYTe4FuXNUBYD+DbM6caVtBT3CAULHHqUQ@mail.gmail.com/" target="_blank" rel="noreferrer">tcp: question about RST at SACK right-most edge</a> <a class="header-anchor" href="#f157e86d2e9f-·-tcp-question-about-rst-at-sack-right-most-edge-1" aria-label="Permalink to &quot;`f157e86d2e9f` · [tcp: question about RST at SACK right-most edge](https://lore.kernel.org/all/CALkdYjV9G2fPfXK7UYTe4FuXNUBYD+DbM6caVtBT3CAULHHqUQ@mail.gmail.com/)&quot;">​</a></h3><p><em>Eugene Siegel (<a href="mailto:elzeigel@gmail.com" target="_blank" rel="noreferrer">elzeigel@gmail.com</a>)｜netdev</em></p><p>讨论 e00431bc93bb 引入的行为：TCP RST 在序列号匹配最右侧 SACK 块右边界时即被接受。发帖者认为这降低了伪造 RST 的门槛——攻击者无需猜测 RCV.NXT，只需让一个乱序 segment 入队，再发送位于该 segment 末尾序列号的 RST 即可断开连接。这是对 TCP RST 验证安全性的质疑讨论。</p><blockquote><p><strong>学习价值</strong>：深入探讨 TCP RST/SACK 交互的安全边界，适合学习 TCP 状态机验证逻辑与 off-path 攻击面分析。</p></blockquote><h3 id="cbd7f820864c-·-patch-net-next-sctp-diag-set-sin6-scope-id-for-ipv6-link-local-lookup-addresses" tabindex="-1"><code>cbd7f820864c</code> · <a href="https://lore.kernel.org/all/409da01d058fee776791de001ffd222069f06090.1795394936.git.lucien.xin@gmail.com/" target="_blank" rel="noreferrer">[PATCH net-next] sctp: diag: set sin6_scope_id for IPv6 link-local lookup addresses</a> <a class="header-anchor" href="#cbd7f820864c-·-patch-net-next-sctp-diag-set-sin6-scope-id-for-ipv6-link-local-lookup-addresses" aria-label="Permalink to &quot;`cbd7f820864c` · [[PATCH net-next] sctp: diag: set sin6_scope_id for IPv6 link-local lookup addresses](https://lore.kernel.org/all/409da01d058fee776791de001ffd222069f06090.1795394936.git.lucien.xin@gmail.com/)&quot;">​</a></h3><p><em>Xin Long (<a href="mailto:lucien.xin@gmail.com" target="_blank" rel="noreferrer">lucien.xin@gmail.com</a>)｜netdev</em></p><p>sctp_diag_dump_one() 在栈上构造 IPv6 查找地址时未设置 sin6_scope_id，而 __sctp_v6_cmp_addr() 对 link-local 地址会比较 scope id，导致 SOCK_DIAG_BY_FAMILY 精确查询无法匹配 link-local association。补丁在查找前将 req-&gt;id.idiag_if 传播到 laddr 和 paddr 的 sin6_scope_id。</p><blockquote><p><strong>学习价值</strong>：小而精的修复，帮助理解 IPv6 link-local 地址 scope id 在 socket 诊断接口中的作用。</p></blockquote><h3 id="bf4231c21e98-·-patch-net-v8-5-5-net-phy-postpone-phy-interrupts-during-sleep-with-mac-managed-pm" tabindex="-1"><code>bf4231c21e98</code> · <a href="https://lore.kernel.org/all/20261123-b4-phylib-mac-pm-irq-v3-v8-5-e9f706e79614@iav.lv/" target="_blank" rel="noreferrer">[PATCH net v8 5/5] net: phy: postpone PHY interrupts during sleep with MAC-managed PM</a> <a class="header-anchor" href="#bf4231c21e98-·-patch-net-v8-5-5-net-phy-postpone-phy-interrupts-during-sleep-with-mac-managed-pm" aria-label="Permalink to &quot;`bf4231c21e98` · [[PATCH net v8 5/5] net: phy: postpone PHY interrupts during sleep with MAC-managed PM](https://lore.kernel.org/all/20261123-b4-phylib-mac-pm-irq-v3-v8-5-e9f706e79614@iav.lv/)&quot;">​</a></h3><p><em>Igor Velkov via B4 Relay (<a href="mailto:devnull+iav.iav.lv@kernel.org" target="_blank" rel="noreferrer">devnull+iav.iav.lv@kernel.org</a>)｜netdev</em></p><p>当 MAC 驱动管理 PHY 电源时，mdio_bus_phy_suspend()/resume() 提前返回，PHY 未获得 irq_suspended 标记，phy_interrupt() 会在睡眠转换期间运行驱动 handler。若 MAC 关闭 MDIO 总线，handler 中的 MDIO 访问会卡死 CPU，suspend 和 resume 两侧均存在此问题（如 Helios64 的 dwmac）。补丁在 MAC-managed PM 场景下推迟 PHY 中断。</p><blockquote><p><strong>学习价值</strong>：展示了 PHY/MAC 电源管理职责划分与中断时序问题，是学习设备电源管理（PM）与网络驱动交互的好材料。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_1175b8c4e492-·-patch-btrfs-zoned-fix-deadlock-between-freeze-and-reclaim-zones-1" tabindex="-1"><code>1175b8c4e492</code> · <a href="https://lore.kernel.org/all/20261123012459.436826-1-mc@raidlab.org/" target="_blank" rel="noreferrer">[PATCH] btrfs: zoned: fix deadlock between freeze and RECLAIM_ZONES</a> <a class="header-anchor" href="#_1175b8c4e492-·-patch-btrfs-zoned-fix-deadlock-between-freeze-and-reclaim-zones-1" aria-label="Permalink to &quot;`1175b8c4e492` · [[PATCH] btrfs: zoned: fix deadlock between freeze and RECLAIM_ZONES](https://lore.kernel.org/all/20261123012459.436826-1-mc@raidlab.org/)&quot;">​</a></h3><p><em>Miroslav Cimerman (<a href="mailto:mc@raidlab.org" target="_blank" rel="noreferrer">mc@raidlab.org</a>)｜lkml</em></p><p>该补丁修复了 btrfs zoned 模式下 freeze 与 RECLAIM_ZONES 之间的死锁：RECLAIM_ZONES 路径中 btrfs_reclaim_block_groups() 通过 sb_start_write() 获取 super write lock，而已持有该锁并等待 data space ticket 的 writer 会与 freeze、reclaim 三方互相等待形成死锁。修复方案是改用 sb_start_write_trylock() 尝试获取锁。</p><blockquote><p><strong>学习价值</strong>：这是一个经典的锁顺序与冻结语义交互的死锁案例，对学习 sb_start_write/freeze_super 机制和 btrfs 空间回收路径非常有价值。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_23a5bfe3552f-·-the-first-rust-wmi-linux-driver-being-developed-is-for-clevo-laptops" tabindex="-1"><code>23a5bfe3552f</code> · <a href="https://www.phoronix.com/news/Rust-WMI-Driver-Clevo-Laptops" target="_blank" rel="noreferrer">The First Rust WMI Linux Driver Being Developed Is For Clevo Laptops</a> <a class="header-anchor" href="#_23a5bfe3552f-·-the-first-rust-wmi-linux-driver-being-developed-is-for-clevo-laptops" aria-label="Permalink to &quot;`23a5bfe3552f` · [The First Rust WMI Linux Driver Being Developed Is For Clevo Laptops](https://www.phoronix.com/news/Rust-WMI-Driver-Clevo-Laptops)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>首个利用内核 Rust WMI（Windows Management Instrumentation）抽象层编写的 Rust 驱动 clevo-laptop 正在开发中，面向 Clevo 笔记本，包括 TUXEDO Computers、Metabox、Sager、XMG 等品牌销售的机型。</p><blockquote><p><strong>学习价值</strong>：是观察 Rust 抽象层（如 WMI）如何被实际驱动消费的优秀案例，体现了 Rust in Linux 从基础设施走向真实驱动的进展。</p></blockquote><h3 id="cb521cec444c-·-patch-samples-rust-dma-add-missing-newline-in-dev-info-call" tabindex="-1"><code>cb521cec444c</code> · <a href="https://lore.kernel.org/all/20261123010430.365536-1-saref012@gmail.com/" target="_blank" rel="noreferrer">[PATCH] samples: rust_dma: add missing newline in dev_info! call</a> <a class="header-anchor" href="#cb521cec444c-·-patch-samples-rust-dma-add-missing-newline-in-dev-info-call" aria-label="Permalink to &quot;`cb521cec444c` · [[PATCH] samples: rust_dma: add missing newline in dev_info! call](https://lore.kernel.org/all/20261123010430.365536-1-saref012@gmail.com/)&quot;">​</a></h3><p><em>Ivan Borovyk (<a href="mailto:saref012@gmail.com" target="_blank" rel="noreferrer">saref012@gmail.com</a>)｜rust-for-linux</em></p><p>samples/rust/rust_dma.rs 的 probe 函数中 dev_info! 调用的格式字符串缺少尾部换行符，导致内核日志中该消息与下一行粘连。补丁补上缺失的换行符。</p><blockquote><p><strong>学习价值</strong>：极小的示例代码清理，可作为 Rust for Linux 样例代码维护的参考。</p></blockquote><h3 id="_54edd5edeaaa-·-rfc-patch-v1-11-11-scripts-add-eh-frame-min-py-eh-frame-coverage-and-size-analyzer" tabindex="-1"><code>54edd5edeaaa</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-12-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 11/11] scripts: Add eh_frame_min.py .eh_frame coverage and size analyzer</a> <a class="header-anchor" href="#_54edd5edeaaa-·-rfc-patch-v1-11-11-scripts-add-eh-frame-min-py-eh-frame-coverage-and-size-analyzer" aria-label="Permalink to &quot;`54edd5edeaaa` · [[RFC PATCH v1 11/11] scripts: Add eh_frame_min.py .eh_frame coverage and size analyzer](https://lore.kernel.org/all/20261122235757.3456048-12-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>新增独立开发工具脚本 scripts/eh_frame_min.py（不由 Kbuild 调用），可分析 x86_64、i386、arm64、arm、riscv 架构下 ELF32/ELF64 可重定位对象、vmlinux 镜像及用户态程序的 .text/.eh_frame/.eh_frame_hdr/.sframe/.orc_unwind 段大小，模拟 .eh_frame 精简收益，报告 DWARF FDE 覆盖率、寄存器规则和 CFA opcode 统计。</p><blockquote><p><strong>学习价值</strong>：对理解内核栈展开（unwinding）机制（.eh_frame、ORC、SFrame）及二进制体积优化工具很有帮助，但与 Rust 子系统关联较弱。</p></blockquote><h3 id="d186cef0f6de-·-rfc-patch-v1-10-11-selftests-perf-events-add-minimal-dwarf-cfi-deferred-user-unwind-test" tabindex="-1"><code>d186cef0f6de</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-11-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 10/11] selftests/perf_events: Add Minimal DWARF CFI deferred user unwind test</a> <a class="header-anchor" href="#d186cef0f6de-·-rfc-patch-v1-10-11-selftests-perf-events-add-minimal-dwarf-cfi-deferred-user-unwind-test" aria-label="Permalink to &quot;`d186cef0f6de` · [[RFC PATCH v1 10/11] selftests/perf_events: Add Minimal DWARF CFI deferred user unwind test](https://lore.kernel.org/all/20261122235757.3456048-11-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>在 tools/testing/selftests/perf_events/ 下新增多架构 kselftest（unwind_user_cfi），测试基于 -O2 -fomit-frame-pointer -fasynchronous-unwind-tables 编译的延迟用户态调用链回溯（PERF_RECORD_CALLCHAIN_DEFERRED）。测试覆盖标准 SP 帧、alloca() VLA 帧、栈重对齐帧（DRAP）、shrink-wrapped 提前返回函数以及匿名 RX JIT 风格帧等多种复杂栈布局。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 kselftest 系统性验证栈回溯在各种编译器优化下的正确性，是学习 unwind 测试方法的优秀范例。</p></blockquote><h3 id="d10146454c60-·-rfc-patch-v1-09-11-riscv-unwind-add-minimal-dwarf-cfi-kernel-unwinder" tabindex="-1"><code>d10146454c60</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-10-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 09/11] riscv/unwind: Add Minimal DWARF CFI kernel unwinder</a> <a class="header-anchor" href="#d10146454c60-·-rfc-patch-v1-09-11-riscv-unwind-add-minimal-dwarf-cfi-kernel-unwinder" aria-label="Permalink to &quot;`d10146454c60` · [[RFC PATCH v1 09/11] riscv/unwind: Add Minimal DWARF CFI kernel unwinder](https://lore.kernel.org/all/20261122235757.3456048-10-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>为 64 位 MMU 启用的 RISC-V 内核新增 CONFIG_UNWINDER_DWARF_CFI，在 arch/riscv/kernel/stacktrace.c 中实现无 frame pointer 的内核栈回溯并支持 HAVE_RELIABLE_STACKTRACE。通过 --eh-frame-hdr 链接 vmlinux，并用 dwarf_cfi_mod_alloc()/dwarf_cfi_mod_free_rcu() 索引可加载模块的 .eh_frame 段。</p><blockquote><p><strong>学习价值</strong>：演示了架构栈回溯代码如何对接通用 DWARF CFI unwinder，以及模块 .eh_frame 的 RCU 管理机制。</p></blockquote><h3 id="_326bbaf35b9d-·-rfc-patch-v1-08-11-riscv-unwind-user-support-minimal-dwarf-cfi-and-fp-user-unwinding" tabindex="-1"><code>326bbaf35b9d</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-9-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 08/11] riscv: unwind_user: Support Minimal DWARF CFI and FP user unwinding</a> <a class="header-anchor" href="#_326bbaf35b9d-·-rfc-patch-v1-08-11-riscv-unwind-user-support-minimal-dwarf-cfi-and-fp-user-unwinding" aria-label="Permalink to &quot;`326bbaf35b9d` · [[RFC PATCH v1 08/11] riscv: unwind_user: Support Minimal DWARF CFI and FP user unwinding](https://lore.kernel.org/all/20261122235757.3456048-9-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>为 RISC-V 接入 CONFIG_HAVE_UNWIND_USER_CFI 和 CONFIG_HAVE_UNWIND_USER_FP，新增 arch/riscv/include/asm/unwind_user.h 和 unwind_user_sigreturn()。定义 RV64 与 RV32/compat 任务的 DWARF CFI 寄存器映射（sp=2, fp/s0=8, ra=1），并按 RISC-V psABI 帧布局实现用户态帧指针回溯与 rt_sigframe 中的寄存器恢复。</p><blockquote><p><strong>学习价值</strong>：展示了用户态回溯如何处理信号帧（sigreturn）和 ABI 帧布局，是理解跨 ABI unwind 实现的好材料。</p></blockquote><h3 id="dd0ae4282b3a-·-rfc-patch-v1-07-11-arm64-unwind-add-minimal-dwarf-cfi-kernel-unwinder" tabindex="-1"><code>dd0ae4282b3a</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-8-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 07/11] arm64/unwind: Add Minimal DWARF CFI kernel unwinder</a> <a class="header-anchor" href="#dd0ae4282b3a-·-rfc-patch-v1-07-11-arm64-unwind-add-minimal-dwarf-cfi-kernel-unwinder" aria-label="Permalink to &quot;`dd0ae4282b3a` · [[RFC PATCH v1 07/11] arm64/unwind: Add Minimal DWARF CFI kernel unwinder](https://lore.kernel.org/all/20261122235757.3456048-8-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>在 arm64 上新增 CONFIG_UNWINDER_DWARF_CFI 作为与 CONFIG_UNWINDER_FRAME_POINTER 并列的内核 unwinder 选项。通过 --eh-frame-hdr 将 .eh_frame_hdr/.eh_frame 放入 vmlinux RO_DATA，同时保留 __pi___eh_frame_start/end 以保证 CONFIG_UNWIND_PATCH_PAC_INTO_SCS 不受影响，且 nVHE EL2 hypervisor 对象和 BPF JIT 帧仍保留 frame pointer。</p><blockquote><p><strong>学习价值</strong>：体现了引入新 unwinder 时需兼顾 PAC/SCS、hypervisor 等既有机制的兼容性考量，架构改造思路值得学习。</p></blockquote><h3 id="_49d27bb2dd48-·-rfc-patch-v1-06-11-arm64-unwind-user-support-minimal-dwarf-cfi-and-fp-user-unwinding" tabindex="-1"><code>49d27bb2dd48</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-7-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 06/11] arm64: unwind_user: Support Minimal DWARF CFI and FP user unwinding</a> <a class="header-anchor" href="#_49d27bb2dd48-·-rfc-patch-v1-06-11-arm64-unwind-user-support-minimal-dwarf-cfi-and-fp-user-unwinding" aria-label="Permalink to &quot;`49d27bb2dd48` · [[RFC PATCH v1 06/11] arm64: unwind_user: Support Minimal DWARF CFI and FP user unwinding](https://lore.kernel.org/all/20261122235757.3456048-7-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>为 arm64 接入 CONFIG_HAVE_UNWIND_USER_CFI 和 CONFIG_HAVE_UNWIND_USER_FP，提供 arch/arm64/include/asm/unwind_user.h 和 unwind_user_sigreturn()。同时支持 64 位 AArch64（sp=31, fp=29, lr=30）和 32 位 AArch32 compat 任务（sp=13, fp=11, lr=14）的寄存器映射，并通过 unwind_user_frame_pointer()/unwind_user_link_register() 处理 DW_CFA_same_value 的叶子函数回溯。</p><blockquote><p><strong>学习价值</strong>：展示了 compat 任务（32/64 位混合）下用户态回溯的寄存器映射处理，对理解多 ABI unwind 很有价值。</p></blockquote><h3 id="_5f7ef0e26da3-·-rfc-patch-v1-05-11-x86-unwind-add-minimal-dwarf-cfi-kernel-unwinder" tabindex="-1"><code>5f7ef0e26da3</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-6-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 05/11] x86/unwind: Add Minimal DWARF CFI kernel unwinder</a> <a class="header-anchor" href="#_5f7ef0e26da3-·-rfc-patch-v1-05-11-x86-unwind-add-minimal-dwarf-cfi-kernel-unwinder" aria-label="Permalink to &quot;`5f7ef0e26da3` · [[RFC PATCH v1 05/11] x86/unwind: Add Minimal DWARF CFI kernel unwinder](https://lore.kernel.org/all/20261122235757.3456048-6-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>为 x86-64 新增 CONFIG_UNWINDER_DWARF_CFI 内核栈回溯器（arch/x86/kernel/unwind_dwarf.c），基于编译器生成的 .eh_frame 和链接器生成的 --eh-frame-hdr 实现 asm/unwind.h 与 HAVE_RELIABLE_STACKTRACE 接口。内核 C 和 Rust 对象以 -fomit-frame-pointer 构建，.eh_frame_hdr/.eh_frame 放入 RO_DATA 以便 mark_rodata_ro 保护，并在 arch/x86/net/bpf_jit_comp.c 中启用 BPF 异常栈遍历。</p><blockquote><p><strong>学习价值</strong>：完整展示了 x86-64 上以 DWARF CFI 替代 ORC/frame-pointer 的 unwinder 实现路径及其与 BPF 的集成。</p></blockquote><h3 id="a832a8e6847e-·-rfc-patch-v1-04-11-objtool-ibt-ignore-eh-frame-relocations-during-endbr-validation" tabindex="-1"><code>a832a8e6847e</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-5-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 04/11] objtool/ibt: Ignore .eh_frame relocations during ENDBR validation</a> <a class="header-anchor" href="#a832a8e6847e-·-rfc-patch-v1-04-11-objtool-ibt-ignore-eh-frame-relocations-during-endbr-validation" aria-label="Permalink to &quot;`a832a8e6847e` · [[RFC PATCH v1 04/11] objtool/ibt: Ignore .eh_frame relocations during ENDBR validation](https://lore.kernel.org/all/20261122235757.3456048-5-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>当 vmlinux.o 以 -fasynchronous-unwind-tables 和 CONFIG_X86_KERNEL_IBT=y 构建时，.eh_frame FDE 头部包含引用 .text 函数起始地址的 PC 相对重定位。由于 .eh_frame 是只读 unwind 元数据而非可执行代码或间接跳转目标，objtool 的 IBT ENDBR 校验应跳过 .eh_frame* 段，与 .orc_unwind_ip 和 .debug_* 段同等对待。</p><blockquote><p><strong>学习价值</strong>：一个典型的工具链协同问题案例：新增段会触发 objtool 校验，理解 IBT 验证逻辑对内核构建流程学习者有帮助。</p></blockquote><h3 id="cac22f9103ab-·-rfc-patch-v1-03-11-scripts-unwind-add-build-time-eh-frame-minifier" tabindex="-1"><code>cac22f9103ab</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-4-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 03/11] scripts, unwind: Add build-time .eh_frame minifier</a> <a class="header-anchor" href="#cac22f9103ab-·-rfc-patch-v1-03-11-scripts-unwind-add-build-time-eh-frame-minifier" aria-label="Permalink to &quot;`cac22f9103ab` · [[RFC PATCH v1 03/11] scripts, unwind: Add build-time .eh_frame minifier](https://lore.kernel.org/all/20261122235757.3456048-4-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>新增无外部依赖的构建时 .eh_frame 精简工具 scripts/min_eh_frame.c（CONFIG_UNWINDER_DWARF_CFI_MINIFY），支持 x86-64、ARM64 和 RISC-V。它在 Kbuild 编译阶段原地重写 .o 文件中的 .eh_frame，剥离 callee-saved 寄存器 spill/restore 操作码和 DW_CFA_GNU_args_size，同时保留 CFA、FP、RA、shrink-wrap 状态栈、DRAP 等回溯必需的信息，以减小 unwind 元数据体积。</p><blockquote><p><strong>学习价值</strong>：展示了如何通过构建期 pass 精简 DWARF 元数据，是理解内核构建工具链定制与 ELF 段操作的实用案例。</p></blockquote><h3 id="c69d142b214d-·-rfc-patch-v1-02-11-unwind-user-support-minimal-dwarf-cfi-user-space-unwinding" tabindex="-1"><code>c69d142b214d</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-3-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 02/11] unwind_user: Support Minimal DWARF CFI user-space unwinding</a> <a class="header-anchor" href="#c69d142b214d-·-rfc-patch-v1-02-11-unwind-user-support-minimal-dwarf-cfi-user-space-unwinding" aria-label="Permalink to &quot;`c69d142b214d` · [[RFC PATCH v1 02/11] unwind_user: Support Minimal DWARF CFI user-space unwinding](https://lore.kernel.org/all/20261122235757.3456048-3-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>扩展通用用户态 unwinder（kernel/unwind/user.c），新增 UNWIND_USER_TYPE_CFI（CONFIG_HAVE_UNWIND_USER_CFI），在 kernel/unwind/user_cfi.c 中解析可执行 VMA 的 ELF PT_GNU_EH_FRAME 头，支持 x86 上 64 位和 32 位 compat 任务回溯。设计上在 mmap_read_lock_killable() 下找到 VMA 后即释放锁再执行可缺页的 copy_from_user()，并缓存 VMA 到 PT_GNU_EH_FRAME 的查找结果（含匿名/JIT VMA 的负缓存）。</p><blockquote><p><strong>学习价值</strong>：演示了内核中安全访问用户态内存的锁与缺页处理模式，以及负缓存设计，工程细节丰富。</p></blockquote><h3 id="c39419804832-·-rfc-patch-v1-01-11-unwind-add-minimal-dwarf-cfi-bytecode-interpreter-and-kunit-tests" tabindex="-1"><code>c39419804832</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-2-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 01/11] unwind: Add Minimal DWARF CFI bytecode interpreter and KUnit tests</a> <a class="header-anchor" href="#c39419804832-·-rfc-patch-v1-01-11-unwind-add-minimal-dwarf-cfi-bytecode-interpreter-and-kunit-tests" aria-label="Permalink to &quot;`c39419804832` · [[RFC PATCH v1 01/11] unwind: Add Minimal DWARF CFI bytecode interpreter and KUnit tests](https://lore.kernel.org/all/20261122235757.3456048-2-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>新增严格有界的 DWARF Call Frame Information（.eh_frame/.eh_frame_hdr）解释器（CONFIG_UNWINDER_DWARF_CFI），状态模型与安全属性对标 SFrame，无需新工具链段或重复用户态 unwind 元数据。struct dwarf_cfi_row 只跟踪 CFA（SP/FP/prologue scratch reg + 偏移，或 DRAP、信号 trampoline 的固定间接模式）、帧指针保存位置等最小状态，而非实现通用 DWARF 表达式虚拟机，并附带 KUnit 测试。</p><blockquote><p><strong>学习价值</strong>：该系列的核心设计：用受限状态机替代完整 DWARF VM 以控制内核攻击面，是学习安全权衡与 KUnit 测试的绝佳素材。</p></blockquote><h3 id="_6832e4b9f03f-·-rfc-patch-v1-00-11-unwind-minimal-dwarf-cfi-stack-unwinding-for-x86-arm64-and-riscv-1" tabindex="-1"><code>6832e4b9f03f</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-1-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 00/11] unwind: Minimal DWARF CFI stack unwinding for x86, arm64, and riscv</a> <a class="header-anchor" href="#_6832e4b9f03f-·-rfc-patch-v1-00-11-unwind-minimal-dwarf-cfi-stack-unwinding-for-x86-arm64-and-riscv-1" aria-label="Permalink to &quot;`6832e4b9f03f` · [[RFC PATCH v1 00/11] unwind: Minimal DWARF CFI stack unwinding for x86, arm64, and riscv](https://lore.kernel.org/all/20261122235757.3456048-1-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜rust-for-linux</em></p><p>该 RFC 系列引入 Minimal DWARF CFI 栈回溯（stack unwinding）机制，同时覆盖用户态延迟调用链（unwind_user / PERF_RECORD_CALLCHAIN_DEFERRED）和内核态栈跟踪（stacktrace.h / HAVE_RELIABLE_STACKTRACE），支持 x86-64、ARM64 和 RISC-V 三种架构，并附带一个独立的 C 语言构建时 .eh_frame 精简工具（scripts/min_eh_frame.c）。该方案使无论是否编译 frame pointer 的二进制都能可靠回溯，且避免引入重复的 .sframe 段。</p><blockquote><p><strong>学习价值</strong>：对理解 perf 调用链采样、DWARF CFI 原理以及跨架构可靠栈回溯的实现非常有价值，是连接 tracing 与二进制格式的优秀学习材料。</p></blockquote><h3 id="_0ea6f89956d7-·-patch-v2-4-4-drm-panthor-refuse-to-export-wb-mmap-bos" tabindex="-1"><code>0ea6f89956d7</code> · <a href="https://lore.kernel.org/all/20261122-pan-drop-dma-buf-hooks-v2-4-2ed42dce9db6@igalia.com/" target="_blank" rel="noreferrer">[PATCH v2 4/4] drm/panthor: Refuse to export WB_MMAP BOs</a> <a class="header-anchor" href="#_0ea6f89956d7-·-patch-v2-4-4-drm-panthor-refuse-to-export-wb-mmap-bos" aria-label="Permalink to &quot;`0ea6f89956d7` · [[PATCH v2 4/4] drm/panthor: Refuse to export WB_MMAP BOs](https://lore.kernel.org/all/20261122-pan-drop-dma-buf-hooks-v2-4-2ed42dce9db6@igalia.com/)&quot;">​</a></h3><p><em>Maíra Canal (<a href="mailto:mcanal@igalia.com" target="_blank" rel="noreferrer">mcanal@igalia.com</a>)｜rust-for-linux</em></p><p>该补丁让 drm/panthor 驱动拒绝导出 WB_MMAP 类型的 buffer object，因为通过 dma-buf 共享时无法保证客户端正确执行 DMA_BUF_IOCTL_SYNC。WC 映射无需维护 CPU cache line，但 WB 映射若漏掉同步，残留的脏 cache line 可能在之后写回并覆盖 GPU 为其他客户端生成的数据。此改动将 PanVK 已有的私有化策略上升为内核强制策略。</p><blockquote><p><strong>学习价值</strong>：展示了 CPU/GPU 缓存一致性与 dma-buf 共享协议之间的微妙交互，是学习 GPU 驱动内存映射（WC vs WB）和缓存一致性问题的好案例。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_84e8868e3c7d-·-kernel-prepatch-7-4-rc4" tabindex="-1"><code>84e8868e3c7d</code> · <a href="https://lwn.net/Articles/1108900/" target="_blank" rel="noreferrer">Kernel prepatch 7.4-rc4</a> <a class="header-anchor" href="#_84e8868e3c7d-·-kernel-prepatch-7-4-rc4" aria-label="Permalink to &quot;`84e8868e3c7d` · [Kernel prepatch 7.4-rc4](https://lwn.net/Articles/1108900/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Linus 发布了 7.4-rc4 内核测试版本，他表示这个 rc 版本体积很大，包含大量散布在各处的小修复，其中驱动修复约占一半，涉及 gpu、networking、usb、iio、nvme、sound 等子系统。整体属于常规的 rc 阶段修复节奏。</p><blockquote><p><strong>学习价值</strong>：通过阅读每周 rc 公告可以了解内核发布周期中各子系统的修复活跃度和典型问题分布。</p></blockquote><h3 id="c5f78d005170-·-linux-7-4-rc4-released-it-s-huge-what-a-surprise" tabindex="-1"><code>c5f78d005170</code> · <a href="https://www.phoronix.com/news/Linux-7.4-rc4-Released" target="_blank" rel="noreferrer">Linux 7.4-rc4 Released: &quot;It&#39;s Huge. What A Surprise.&quot;</a> <a class="header-anchor" href="#c5f78d005170-·-linux-7-4-rc4-released-it-s-huge-what-a-surprise" aria-label="Permalink to &quot;`c5f78d005170` · [Linux 7.4-rc4 Released: &quot;It&#39;s Huge. What A Surprise.&quot;](https://www.phoronix.com/news/Linux-7.4-rc4-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4-rc4 作为 7.4 周期最新的每周测试候选版本发布。值得注意的是，该周期的开发活动依然非常活跃，其中相当一部分 bug 报告和补丁由 AI/LLM 生成并驱动。</p><blockquote><p><strong>学习价值</strong>：展示了 AI 生成补丁正在实际影响内核开发流程，是观察社区工作方式演变的一个有趣信号。</p></blockquote><h3 id="a057f7200978-·-amd-preps-more-graphics-driver-fixes-for-linux-7-5-more-dcn6-enablement" tabindex="-1"><code>a057f7200978</code> · <a href="https://www.phoronix.com/news/AMDGPU-More-DCN6-Linux-7.5" target="_blank" rel="noreferrer">AMD Preps More Graphics Driver Fixes For Linux 7.5, More DCN6 Enablement</a> <a class="header-anchor" href="#a057f7200978-·-amd-preps-more-graphics-driver-fixes-for-linux-7-5-more-dcn6-enablement" aria-label="Permalink to &quot;`a057f7200978` · [AMD Preps More Graphics Driver Fixes For Linux 7.5, More DCN6 Enablement](https://www.phoronix.com/news/AMDGPU-More-DCN6-Linux-7.5)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 本周提交了最新一批 AMDGPU 内核图形驱动和 AMDKFD 计算驱动的更新，计划在即将到来的 Linux 7.5 merge window 中合入，其中包括更多 DCN6 显示引擎的启用工作。</p><blockquote><p><strong>学习价值</strong>：可借此了解 AMDGPU/AMDKFD 驱动的开发节奏和 DCN6 等新硬件支持如何逐步进入主线。</p></blockquote><h3 id="_895d938d11ff-·-cachyos-november-2026-released-with-eac-linux-v2-support-new-recovery-tool" tabindex="-1"><code>895d938d11ff</code> · <a href="https://www.phoronix.com/news/CachyOS-November-2026" target="_blank" rel="noreferrer">CachyOS November 2026 Released With EAC Linux v2 Support, New Recovery Tool</a> <a class="header-anchor" href="#_895d938d11ff-·-cachyos-november-2026-released-with-eac-linux-v2-support-new-recovery-tool" aria-label="Permalink to &quot;`895d938d11ff` · [CachyOS November 2026 Released With EAC Linux v2 Support, New Recovery Tool](https://www.phoronix.com/news/CachyOS-November-2026)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>基于 Arch Linux 的 CachyOS 发行版发布了 2026 年 11 月的 ISO 刷新版本，新增 EAC（Easy Anti-Cheat）Linux v2 支持和新的恢复工具。这是发行版层面的更新，与内核主线开发无直接关系。</p><blockquote><p><strong>学习价值</strong>：对内核学习者价值有限，仅可作为了解发行版如何跟进内核与游戏反作弊生态的参考。</p></blockquote><h3 id="_30bd37818e26-·-intel-coral-rapids-razor-lake-model-ids-submitted-for-linux-7-4-rc4" tabindex="-1"><code>30bd37818e26</code> · <a href="https://www.phoronix.com/news/Coral-Rapids-Razor-Lake-7.4" target="_blank" rel="noreferrer">Intel Coral Rapids &amp; Razor Lake Model IDs Submitted For Linux 7.4-rc4</a> <a class="header-anchor" href="#_30bd37818e26-·-intel-coral-rapids-razor-lake-model-ids-submitted-for-linux-7-4-rc4" aria-label="Permalink to &quot;`30bd37818e26` · [Intel Coral Rapids &amp; Razor Lake Model IDs Submitted For Linux 7.4-rc4](https://www.phoronix.com/news/Coral-Rapids-Razor-Lake-7.4)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>本周进入 Linux 7.4-rc4 的 x86 修复中包含了 Intel 下一代 Coral Rapids 服务器处理器和 Razor Lake 客户端处理器的 model ID 添加，用于内核正确识别这些新平台。</p><blockquote><p><strong>学习价值</strong>：展示了新 CPU 平台支持的第一步往往只是添加 model ID，是理解 x86 架构代码演进入口的好例子。</p></blockquote><h3 id="_5acfd0e6eed8-·-cachyos-releases-package-installer-2-0-with-convenient-aur-flatpak-appimage-support" tabindex="-1"><code>5acfd0e6eed8</code> · <a href="https://www.phoronix.com/news/CachyOS-Package-Installer-2.0" target="_blank" rel="noreferrer">CachyOS Releases Package Installer 2.0 With Convenient AUR / Flatpak / AppImage Support</a> <a class="header-anchor" href="#_5acfd0e6eed8-·-cachyos-releases-package-installer-2-0-with-convenient-aur-flatpak-appimage-support" aria-label="Permalink to &quot;`5acfd0e6eed8` · [CachyOS Releases Package Installer 2.0 With Convenient AUR / Flatpak / AppImage Support](https://www.phoronix.com/news/CachyOS-Package-Installer-2.0)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>CachyOS 开发者正式发布了 Package Installer 2.0，为这个基于 Arch Linux 的发行版提供了全新的 UI/UX，方便管理 AUR、Flatpak 和 AppImage 等多种软件包格式。该内容属于发行版用户空间工具，与内核开发无关。</p><blockquote><p><strong>学习价值</strong>：对内核学习基本没有价值，属于发行版生态新闻。</p></blockquote><h3 id="_7cbec6ee3122-·-linux-7-5-to-introduce-initial-mainline-support-for-ambarella-socs" tabindex="-1"><code>7cbec6ee3122</code> · <a href="https://www.phoronix.com/news/Linux-7.5-Ambarella-SoCs" target="_blank" rel="noreferrer">Linux 7.5 To Introduce Initial Mainline Support For Ambarella SoCs</a> <a class="header-anchor" href="#_7cbec6ee3122-·-linux-7-5-to-introduce-initial-mainline-support-for-ambarella-socs" aria-label="Permalink to &quot;`7cbec6ee3122` · [Linux 7.5 To Introduce Initial Mainline Support For Ambarella SoCs](https://www.phoronix.com/news/Linux-7.5-Ambarella-SoCs)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>在 Linux 7.4 中合入了部分 Device Tree 和驱动准备补丁之后，即将到来的 Linux 7.5 内核将引入对 Ambarella SoC 的初始主线支持，首个目标 SoC 是 CV75。这标志着又一家嵌入式视觉芯片厂商进入主线内核。</p><blockquote><p><strong>学习价值</strong>：展示了新 SoC 进入主线内核的典型路径：先 Device Tree 和基础驱动，再逐步完善平台支持。</p></blockquote><h3 id="_015b6d2b837f-·-psr2-panel-replay-pipe-joiner-to-be-supported-for-intel-on-linux-7-5" tabindex="-1"><code>015b6d2b837f</code> · <a href="https://www.phoronix.com/news/Intel-PSR2-Panel-Replay-Joiner" target="_blank" rel="noreferrer">PSR2 &amp; Panel Replay + Pipe Joiner To Be Supported For Intel On Linux 7.5</a> <a class="header-anchor" href="#_015b6d2b837f-·-psr2-panel-replay-pipe-joiner-to-be-supported-for-intel-on-linux-7-5" aria-label="Permalink to &quot;`015b6d2b837f` · [PSR2 &amp; Panel Replay + Pipe Joiner To Be Supported For Intel On Linux 7.5](https://www.phoronix.com/news/Intel-PSR2-Panel-Replay-Joiner)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Intel 的 pipe joiner 功能允许将多个内部 display pipe 组合起来驱动单个超高分辨率或高刷新率显示器，四 pipe ultra joiner 配置可支持 8K 和 4K@240Hz 显示。Linux 7.5 将首次支持在 joiner 模式下同时启用 Panel Replay 和 PSR2 节能特性。</p><blockquote><p><strong>学习价值</strong>：有助于理解 i915/xe 显示驱动中 pipe joiner 与 PSR2/Panel Replay 等电源管理特性之间的交互约束。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>6832e4b9f03f</code> · <a href="https://lore.kernel.org/all/20261122235757.3456048-1-irogers@google.com/" target="_blank" rel="noreferrer">[RFC PATCH v1 00/11] unwind: Minimal DWARF CFI stack unwinding for x86, arm64, and riscv</a></li><li><code>f157e86d2e9f</code> · <a href="https://lore.kernel.org/all/CALkdYjV9G2fPfXK7UYTe4FuXNUBYD+DbM6caVtBT3CAULHHqUQ@mail.gmail.com/" target="_blank" rel="noreferrer">tcp: question about RST at SACK right-most edge</a></li><li><code>a45fd5bb7d24</code> · <a href="https://lore.kernel.org/all/20261123011320.4032340-1-linma@zju.edu.cn/" target="_blank" rel="noreferrer">[PATCH net] rxrpc: Bound the OOB challenge queue per connection</a></li><li><code>1175b8c4e492</code> · <a href="https://lore.kernel.org/all/20261123012459.436826-1-mc@raidlab.org/" target="_blank" rel="noreferrer">[PATCH] btrfs: zoned: fix deadlock between freeze and RECLAIM_ZONES</a></li><li><code>36585244d182</code> · <a href="https://lore.kernel.org/all/20261122-b4-ksm_fixv2-v3-1-f78ea7779746@linux.dev/" target="_blank" rel="noreferrer">[PATCH v3] mm/ksm: prevent zero-page remapping during ksmd-triggered THP splits</a></li></ul>',162)])])}const h=r(t,[["render",l]]);export{u as __pageData,h as default};
